<?php
declare(strict_types=1);
require_once __DIR__.'/../config/conexao.php';
verificarAcesso('admin');
$message='';
if($_SERVER['REQUEST_METHOD']==='POST'){
    validarCsrf();
    try{
        $action=(string)($_POST['acao']??'');
        if($action==='banner'){
            db()->prepare('UPDATE banners_site SET titulo=?,texto_alternativo=?,imagem_url=?,categoria_slug=?,link_url=?,ordem=?,ativo=? WHERE id_banner=?')->execute([trim((string)($_POST['titulo']??'')),trim((string)($_POST['alt']??'')),trim((string)($_POST['imagem']??'')),trim((string)($_POST['categoria']??'todos'))?:'todos',trim((string)($_POST['link']??'#ofertas')),max(0,(int)($_POST['ordem']??0)),isset($_POST['ativo'])?1:0,(int)($_POST['id']??0)]);
            $message='Banner salvo.';
        }elseif($action==='promocao'){
            db()->prepare('UPDATE promocoes_site SET etiqueta=?,titulo=?,chamada=?,imagem_url=?,categoria_slug=?,ordem=?,ativo=?,inicio_vigencia=?,fim_vigencia=? WHERE id_promocao=?')->execute([trim((string)($_POST['etiqueta']??'')),trim((string)($_POST['titulo']??'')),trim((string)($_POST['chamada']??'')),trim((string)($_POST['imagem']??''))?:null,trim((string)($_POST['categoria']??'todos'))?:'todos',max(0,(int)($_POST['ordem']??0)),isset($_POST['ativo'])?1:0,trim((string)($_POST['inicio']??''))?:null,trim((string)($_POST['fim']??''))?:null,(int)($_POST['id']??0)]);
            $message='Promoção salva.';
        }elseif($action==='encarte'){
            $price=(float)($_POST['preco']??-1);$unit=(string)($_POST['unidade']??'UN');
            if($price<0||!in_array($unit,['UN','KG'],true))throw new RuntimeException('Dados inválidos.');
            db()->prepare('UPDATE itens_encarte_site SET nome=?,detalhe=?,preco=?,tipo_medida=?,ordem=?,ativo=? WHERE id_item_encarte=?')->execute([trim((string)($_POST['nome']??'')),trim((string)($_POST['detalhe']??'')),$price,$unit,max(0,(int)($_POST['ordem']??0)),isset($_POST['ativo'])?1:0,(int)($_POST['id']??0)]);
            $message='Oferta do encarte salva.';
        }elseif($action==='texto'){
            db()->prepare('UPDATE conteudo_site SET valor=? WHERE chave=?')->execute([trim((string)($_POST['valor']??'')),(string)($_POST['chave']??'')]);
            $message='Texto salvo.';
        }
    }catch(Throwable $error){$message='Não foi possível salvar. Confira os dados e tente novamente.';}
}
$banners=db()->query('SELECT * FROM banners_site ORDER BY ordem,id_banner')->fetchAll();
$promos=db()->query('SELECT * FROM promocoes_site ORDER BY tipo,ordem,id_promocao')->fetchAll();
$items=db()->query('SELECT * FROM itens_encarte_site ORDER BY ordem,id_item_encarte')->fetchAll();
$copy=db()->query('SELECT chave,valor FROM conteudo_site ORDER BY chave')->fetchAll();
$categories=db()->query('SELECT slug,nome FROM categorias ORDER BY id_categoria')->fetchAll();
?><!doctype html><html lang="pt-BR"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Conteúdo do site · Alvorada</title><link rel="stylesheet" href="/assets/css/style.css?v=44"><style>.cms{padding:28px 0 60px}.cms-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:14px;margin:12px 0 28px}.cms-card{margin:0;padding:18px}.cms-card label{display:block;margin:8px 0;font-size:.85rem}.cms-card input,.cms-card select,.cms-card textarea{width:100%;margin-top:4px}.cms-card .row{display:grid;grid-template-columns:1fr 1fr;gap:10px}.cms-card .check{display:flex;align-items:center;gap:8px}.cms-card .check input{width:auto}.cms-card button{width:100%;margin-top:8px}@media(max-width:720px){.cms-grid{grid-template-columns:1fr}}</style></head><body><main class="container cms"><div class="section-head"><div><p class="muted">Painel administrativo</p><h1>Conteúdo do site</h1></div><a class="button light" href="/admin/painel.php">Voltar ao painel</a></div><?php if($message):?><p class="notice" role="status"><?=h($message)?></p><?php endif;?>
<h2>Banners da página inicial</h2><div class="cms-grid"><?php foreach($banners as $banner):?><form class="card form cms-card" method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="acao" value="banner"><input type="hidden" name="id" value="<?=$banner['id_banner']?>"><label>Título<input name="titulo" maxlength="140" value="<?=h($banner['titulo'])?>" required></label><label>Texto alternativo<input name="alt" maxlength="255" value="<?=h($banner['texto_alternativo'])?>" required></label><label>Caminho da imagem<input name="imagem" maxlength="255" value="<?=h($banner['imagem_url'])?>" required></label><div class="row"><label>Categoria<select name="categoria"><option value="todos" <?=$banner['categoria_slug']==='todos'?'selected':''?>>Todas</option><?php foreach($categories as $category):?><option value="<?=h($category['slug'])?>" <?=$banner['categoria_slug']===$category['slug']?'selected':''?>><?=h($category['nome'])?></option><?php endforeach;?></select></label><label>Link<input name="link" maxlength="255" value="<?=h($banner['link_url'])?>" required></label></div><div class="row"><label>Ordem<input type="number" name="ordem" min="0" value="<?=$banner['ordem']?>"></label><label class="check"><input type="checkbox" name="ativo" <?=$banner['ativo']?'checked':''?>> Ativo</label></div><button>Salvar banner</button></form><?php endforeach;?></div>
<h2>Cartões promocionais e encarte</h2><div class="cms-grid"><?php foreach($promos as $promo):?><form class="card form cms-card" method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="acao" value="promocao"><input type="hidden" name="id" value="<?=$promo['id_promocao']?>"><label>Identificação<input value="<?=h($promo['slug'].' · '.$promo['tipo'])?>" disabled></label><label>Etiqueta<input name="etiqueta" maxlength="100" value="<?=h($promo['etiqueta'])?>" required></label><label>Título<input name="titulo" maxlength="160" value="<?=h($promo['titulo'])?>" required></label><label>Chamada<input name="chamada" maxlength="160" value="<?=h($promo['chamada'])?>" required></label><label>Caminho da imagem<input name="imagem" maxlength="255" value="<?=h($promo['imagem_url']??'')?>"></label><div class="row"><label>Categoria<select name="categoria"><option value="todos" <?=$promo['categoria_slug']==='todos'?'selected':''?>>Todas</option><?php foreach($categories as $category):?><option value="<?=h($category['slug'])?>" <?=$promo['categoria_slug']===$category['slug']?'selected':''?>><?=h($category['nome'])?></option><?php endforeach;?></select></label><label>Ordem<input type="number" name="ordem" min="0" value="<?=$promo['ordem']?>"></label></div><div class="row"><label>Início<input type="date" name="inicio" value="<?=h($promo['inicio_vigencia']??'')?>"></label><label>Fim<input type="date" name="fim" value="<?=h($promo['fim_vigencia']??'')?>"></label></div><label class="check"><input type="checkbox" name="ativo" <?=$promo['ativo']?'checked':''?>> Ativo</label><button>Salvar promoção</button></form><?php endforeach;?></div>
<h2>Produtos e preços do encarte</h2><div class="cms-grid"><?php foreach($items as $item):?><form class="card form cms-card" method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="acao" value="encarte"><input type="hidden" name="id" value="<?=$item['id_item_encarte']?>"><label>Produto<input name="nome" maxlength="140" value="<?=h($item['nome'])?>" required></label><div class="row"><label>Embalagem<input name="detalhe" maxlength="80" value="<?=h($item['detalhe'])?>" required></label><label>Preço (R$)<input type="number" name="preco" min="0" step="0.01" value="<?=$item['preco']?>" required></label></div><div class="row"><label>Unidade<select name="unidade"><option value="UN" <?=$item['tipo_medida']==='UN'?'selected':''?>>Unidade/pacote</option><option value="KG" <?=$item['tipo_medida']==='KG'?'selected':''?>>Quilo</option></select></label><label>Ordem<input type="number" name="ordem" min="0" value="<?=$item['ordem']?>"></label></div><label class="check"><input type="checkbox" name="ativo" <?=$item['ativo']?'checked':''?>> Ativo no encarte</label><button>Salvar oferta</button></form><?php endforeach;?></div>
<h2>Textos do site</h2><div class="cms-grid"><?php foreach($copy as $entry):?><form class="card form cms-card" method="post"><input type="hidden" name="csrf" value="<?=h(csrf())?>"><input type="hidden" name="acao" value="texto"><input type="hidden" name="chave" value="<?=h($entry['chave'])?>"><label><?=h($entry['chave'])?><textarea name="valor" rows="3" required><?=h($entry['valor'])?></textarea></label><button>Salvar texto</button></form><?php endforeach;?></div></main><?php require __DIR__.'/../includes/site-footer.php'; ?>
</body></html>
